/* prog17_whitespace_trim.c
 * Reimplementation of the original binary's behaviour:
 *   - Takes the first command‑line argument.
 *   - Truncates it to 400 characters.
 *   - Trims leading and trailing whitespace.
 *   - Collapses internal runs of whitespace to a single space.
 *   - Prints the result, or "EMPTY" if the result is empty or no argument is given.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    /* No argument → print EMPTY */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *in = argv[1];
    size_t len = strlen(in);
    if (len > 400) {
        len = 400;               /* truncate to the first 400 characters */
    }

    char out[401];               /* enough for the truncated input + NUL */
    size_t out_idx = 0;
    int i = 0;

    /* Skip leading whitespace */
    while (i < (int)len && isspace((unsigned char)in[i])) {
        ++i;
    }

    int pending_space = 0;       /* true if we have seen whitespace after a word */

    for ( ; i < (int)len; ++i) {
        unsigned char c = (unsigned char)in[i];
        if (isspace(c)) {
            pending_space = 1;   /* remember that a whitespace run occurred */
        } else {
            if (pending_space && out_idx > 0) {
                out[out_idx++] = ' ';   /* collapse the run to a single space */
            }
            out[out_idx++] = c;          /* copy the non‑whitespace character */
            pending_space = 0;
        }
    }

    out[out_idx] = '\0';         /* NUL‑terminate the result */

    if (out_idx == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }

    return 0;
}
